source(file.path(commandArgs(TRUE)[1],'code/common.R'));s<-args[2];out<-file.path(root,s);d<-fread(file.path(out,'diagnosis.tsv.gz'),na.strings=c('','NA'));x<-load_major(file.path(old,s));ids<-colnames(x[['RNA']]);stopifnot(identical(ids,d$cell_id));q<-LayerData(x,assay='RNA',layer='data');counts<-LayerData(x,assay='RNA',layer='counts');gm<-fread(file.path(old,s,'tables/gene_identity.tsv'))
genes<-c('KRT7','KRT19','UPK2','KRT6B','KRT13','KRTDAP','EPCAM','CD3D','CD3E','TRAC','NKG7','GNLY','LST1','LYZ','C1QA','TYROBP','COL1A1','DCN','LUM','COL3A1','PECAM1','VWF','CDH5','TPSAB1','CPA3','KIT','MS4A1','CD79A','BANK1','MZB1','JCHAIN','TNFRSF17','IGKC','IGHA1','RGS5','MYH11','ACTG2','PDGFRB');gm<-gm[symbol%in%genes&feature_id%in%rownames(q)];q<-q[gm$feature_id,,drop=FALSE];c<-counts[gm$feature_id,,drop=FALSE]>0;ans<-list();j<-0L
for(route in c('blca','hpca')) {lab<-d[[paste0('singler_',route,'_pruned_labels')]];lab[is.na(lab)]<-'Unknown';for(scope in c('original_Unknown','original_known'))for(k in unique(lab)){hit<-lab==k & if(scope=='original_Unknown')d$final_major=='Unknown' else d$final_major!='Unknown';if(!any(hit))next;j<-j+1L;ans[[j]]<-data.table(route=route,scope=scope,candidate=k,n=sum(hit),feature_id=gm$feature_id,symbol=gm$symbol,mean_log_normalized=Matrix::rowMeans(q[,hit,drop=FALSE]),pct_positive=Matrix::rowMeans(c[,hit,drop=FALSE]))}}
fwrite(rbindlist(ans),file.path(out,'candidate_marker_statistics.tsv'),sep='\t');cat('MARKER_SUMMARY_COMPLETE',s,'\n')
